function mood(p){if(!p)return'💤';if(p.asleep)return'💤';if(p.stats.hunger<24)return'🥺';if(p.stats.hygiene<25)return'😵‍💫';if(p.stats.happiness>75)return'💖';if(p.stats.energy<20)return'😴';return'😊'}
function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function render(){let p=state.pet;if(p)agePet(p);document.getElementById('day-pill').textContent=p?`🌱 Day ${p.day} of 20`:'🌱 Waiting for a hatchling';let area=document.getElementById('pet-area');if(!p){area.innerHTML='<div class="scene-empty"><div class="egg-card"><span class="egg">🥚</span><h2>A little life, waiting</h2><p>Every egg carries a one-of-a-kind soul. Tap to hatch your new friend and begin your story together.</p><button class="primary" onclick="hatch()">Hatch your egg ✨</button></div></div>'}else{area.innerHTML=petSvg(p)+`<div class="pet-name-tag">${p.name} · ${p.species}</div><div class="pet-mood">${mood(p)}</div>${p.poop?`<button class="poop" onclick="care('clean')" aria-label="Clean up waste">💩</button>`:''}`;document.querySelector('.scene-empty')?.remove()}
let title=document.getElementById('pet-title'),subtitle=document.getElementById('pet-subtitle'),avatar=document.getElementById('profile-avatar'),badge=document.getElementById('stage-badge');if(p){title.textContent=p.name;subtitle.textContent=`${p.species} · ${p.trait} · age ${p.day} ${p.day===1?'day':'days'}`;avatar.innerHTML=petSvg(p).replace('class="pet-svg','class="pet-svg mini-svg');badge.textContent=stages[p.stage]}else{title.textContent='An egg is waiting';subtitle.textContent='Your next tiny adventure starts here';avatar.textContent='🥚';badge.textContent='Unhatched'}
let meters=document.getElementById('meters');meters.innerHTML=p?needData.map(([key,icon,label])=>`<div><div class="meter-label"><span>${icon} ${label}</span><span>${Math.round(p.stats[key])}%</span></div><div class="track"><div class="fill ${p.stats[key]<25?'low':p.stats[key]<50?'mid':''}" style="width:${p.stats[key]}%"></div></div></div>`).join(''):'<p class="empty-needs">Your hatchling’s needs will appear here. Keep their tummy full and little heart bright.</p>';
let acts=[['feed','🍓','Feed'],['play','🪁','Play'],['love','💗','Cuddle'],['clean','🧹','Clean up'],['shower','🚿','Bathe'],['treat','🎁','Treat']];document.getElementById('care-actions').innerHTML=acts.map(([id,e,n])=>`<button class="action" onclick="care('${id}')" ${!p?'disabled':''}><span class="emoji">${e}</span><span>${n}</span></button>`).join('');document.getElementById('care-note').textContent=p?(p.poop?`${p.name} left ${p.poop} little mess${p.poop>1?'es':''}. A tidy home means a happy heart.`:`${p.name} is ${p.trait}. Their unique DNA: ${p.dna.slice(0,4)} · ${p.dna.slice(4,8)} · ${p.dna.slice(8,12)} · ${p.dna.slice(12)}`):'Every little gesture helps your new friend thrive.';
let gs=document.getElementById('games-list');gs.innerHTML=p?p.games.map(id=>{let g=gamePool.find(x=>x.id===id);return `<button class="game-btn" onclick="startGame('${id}')" ${p.stats.energy<10||p.asleep?'disabled':''}><span class="game-icon">${g.icon}</span><span><strong>${g.name}</strong><small>${g.desc}</small></span></button>`}).join(''):'<div class="games-locked">Hatch your egg to discover the four games your pet loves most.</div>';document.getElementById('game-count').textContent=p?'4 games · '+p.playCount+' played':'4 games per lifetime';document.getElementById('sleep-btn').textContent=p?(p.asleep?'☀️ Wake up':'🌙 Lights out'):'🌙 Lights out';document.getElementById('sleep-btn').disabled=!p;
let legacy=document.getElementById('legacy-list');legacy.innerHTML=state.legacy.length?state.legacy.slice(0,3).map(x=>`<div class="legacy-row"><span class="legacy-creature">${x.emoji}</span><div><strong>${x.name}</strong><small>${x.species} · ${stages[x.stage]} · DNA ${x.dna.slice(0,8)}</small></div><span class="legacy-count">${x.score} ✦</span></div>`).join(''):'<p class="legacy-empty">Your first little life will live here forever.</p>';document.getElementById('last-care').textContent=p?`${p.poop?`💩 ${p.poop} mess${p.poop>1?'es':''} to tidy`:'A little love goes a long way'} · ${p.score} ✦`:'A little love goes a long way';save()}
function animate(className){let svg=document.getElementById('pet-svg');if(svg){svg.classList.remove('bounce','shake');void svg.offsetWidth;svg.classList.add(className);setTimeout(()=>svg.classList.remove(className),650)}}
function care(action){let p=state.pet;if(!p)return;if(p.asleep&&action!=='clean'){notify(`${p.name} is sleeping. Wake them gently first.`);return}let m=p.stats;let lines={feed:['A berry snack! Yum! 🍓',()=>{m.hunger=clamp(m.hunger+29);m.happiness=clamp(m.happiness+4);p.feedCount++}],play:['A lovely play together! 🪁',()=>{m.happiness=clamp(m.happiness+19);m.energy=clamp(m.energy-9);m.affection=clamp(m.affection+4);p.playCount++}],love:['A big, warm cuddle. 💗',()=>{m.affection=clamp(m.affection+22);m.happiness=clamp(m.happiness+11)}],clean:['All clean and cozy! 🧹',()=>{if(!p.poop){m.hygiene=clamp(m.hygiene+4)}else{p.cleanCount+=p.poop;p.poop=0;m.hygiene=clamp(m.hygiene+18);m.happiness=clamp(m.happiness+8)}}],shower:['Fresh as a daisy! 🚿',()=>{m.hygiene=clamp(m.hygiene+31);m.happiness=clamp(m.happiness+5)}],treat:['A tiny surprise! 🎁',()=>{m.hunger=clamp(m.hunger+10);m.happiness=clamp(m.happiness+15);m.affection=clamp(m.affection+8)}]};lines[action][1]();p.careCount++;p.score+=2;p.last=Date.now();animate(action==='play'?'bounce':'shake');notify(lines[action][0]);render()}
function toggleSleep(){let p=state.pet;if(!p)return;p.asleep=!p.asleep;p.last=Date.now();notify(p.asleep?`${p.name} is tucked in. Sweet dreams! 🌙`:`Good morning, ${p.name}! ☀️`);render()}
function openModal(html){document.getElementById('modal-root').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><section class="modal">${html}</section></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function startGame(id){let p=state.pet;if(!p||p.asleep||p.stats.energy<10)return;let g=gamePool.find(x=>x.id===id);if(id==='bug'||id==='bubble'||id==='garden'||id==='star'){let icon=id==='bug'?'✨':id==='bubble'?'🫧':id==='garden'?'🌱':'⭐';let label=id==='bug'?'fireflies':id==='bubble'?'bubbles':id==='garden'?'seeds':'stars';let goal=id==='bubble'?8:id==='star'?6:5;openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">A little game</div><h2>${g.name}</h2><p class="modal-desc">Tap ${goal} ${label} before they drift away!</p><div class="game-score">${icon} <span id="game-score">0</span> / ${goal}</div><div class="tap-zone" id="tap-zone"><button class="target" id="target" onclick="tapTarget('${id}',${goal})">${icon}</button><span class="game-instruction">Tap the little target!</span></div>`);setTimeout(()=>{let t=document.getElementById('target');if(t)t.classList.add('target-ready')},80)}else if(id==='memory'){let tiles=['🌙','🌿','🍄','🌼'];let pair=[...tiles,...tiles].sort(()=>Math.random()-.5);openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">A little game</div><h2>${g.name}</h2><p class="modal-desc">Find all four matching pairs.</p><div class="memory-grid">${pair.map((e,i)=>`<button class="memory-tile" data-value="${e}" onclick="flipTile(this)">✦</button>`).join('')}</div><p class="memory-status" id="memory-status">Find the matching pairs!</p>`)}else if(id==='rhythm'){let seq=Array.from({length:4},()=>Math.floor(Math.random()*4));openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">A little game</div><h2>${g.name}</h2><p class="modal-desc">Watch the lights, then repeat the rhythm.</p><div class="rhythm-pads">${['🌿','🌙','⭐','🌼'].map((e,i)=>`<button class="rhythm-pad" id="pad${i}" onclick="rhythmInput(${i})">${e}</button>`).join('')}</div><p class="memory-status" id="rhythm-status">Watch carefully…</p>`);window.rhythmSeq=seq;window.rhythmInputN=0;setTimeout(()=>playSequence(seq),500)}else if(id==='shell'){openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">A little game</div><h2>${g.name}</h2><p class="modal-desc">Which shell is hiding the pearl?</p><div class="shell-row">${[0,1,2].map(i=>`<button class="shell" onclick="pickShell(${i})">🐚</button>`).join('')}</div><p class="memory-status" id="shell-status">Pick a shell!</p>`);window.pearl=Math.floor(Math.random()*3)}else if(id==='cloud'){let answer=2+Math.floor(Math.random()*4);openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">A little game</div><h2>${g.name}</h2><p class="modal-desc">How many clouds can you count?</p><div class="cloud-row">${Array.from({length:answer},()=>'<span>☁️</span>').join('')}</div><div class="number-row">${[2,3,4,5].map(n=>`<button onclick="cloudAnswer(${n},${answer})">${n}</button>`).join('')}</div>`)} }
function finishGame(points,msg){let p=state.pet;if(!p)return;p.stats.happiness=clamp(p.stats.happiness+12);p.stats.energy=clamp(p.stats.energy-7);p.stats.affection=clamp(p.stats.affection+3);p.score+=points;p.playCount++;p.last=Date.now();save();closeModal();animate('bounce');notify(`${msg} +${points} stardust!`);render()}
function tapTarget(id,goal){let score=+(document.getElementById('game-score')?.textContent||0)+1;let el=document.getElementById('game-score');if(el)el.textContent=score;if(score>=goal){finishGame(12,'You did it! Your friend had a blast.');return}let t=document.getElementById('target'),zone=document.getElementById('tap-zone');if(t&&zone){t.style.left=(8+Math.random()*74)+'%';t.style.top=(10+Math.random()*65)+'%';t.textContent=id==='bug'?'✨':id==='bubble'?'🫧':id==='garden'?'🌱':'⭐'}}
function flipTile(tile){if(tile.classList.contains('revealed')||document.querySelectorAll('.memory-tile.revealed:not(.matched)').length>=2)return;tile.textContent=tile.dataset.value;tile.classList.add('revealed');let open=[...document.querySelectorAll('.memory-tile.revealed:not(.matched)')];if(open.length===2){if(open[0].dataset.value===open[1].dataset.value){open.forEach(x=>x.classList.add('matched'));if(document.querySelectorAll('.memory-tile.matched').length===8){setTimeout(()=>finishGame(16,'Perfect memory!'),450)}}else setTimeout(()=>open.forEach(x=>{x.classList.remove('revealed');x.textContent='✦'}),700)}}
function playSequence(seq){let i=0;let interval=setInterval(()=>{let e=document.getElementById('pad'+seq[i]);if(!e){clearInterval(interval);return}e.classList.add('lit');setTimeout(()=>e.classList.remove('lit'),330);i++;if(i>=seq.length){clearInterval(interval);let s=document.getElementById('rhythm-status');if(s)s.textContent='Your turn — repeat the rhythm!'}},500)}
function rhythmInput(n){if(!window.rhythmSeq)return;let seq=window.rhythmSeq;let p=document.getElementById('pad'+n);p.classList.add('lit');setTimeout(()=>p.classList.remove('lit'),180);if(seq[window.rhythmInputN]!==n){window.rhythmInputN=0;document.getElementById('rhythm-status').textContent='Oops! Watch one more time…';setTimeout(()=>playSequence(seq),700);return}window.rhythmInputN++;if(window.rhythmInputN===seq.length)finishGame(15,'What a lovely rhythm!')}
function pickShell(n){let el=document.getElementById('shell-status');if(n===window.pearl){el.textContent='A pearl! You found it!';setTimeout(()=>finishGame(12,'Shiny shell success!'),450)}else{el.textContent='Not this one… try again!';document.querySelectorAll('.shell')[n].textContent='🐚'}}
function cloudAnswer(n,answer){if(n===answer)finishGame(10,'Great counting!');else{notify('Not quite — count the clouds again!')}}
function showLegacy(){if(!state.legacy.length){notify('Your first little life will live here forever.');return}openModal(`<button class="close-modal" onclick="closeModal()">×</button><div class="modal-kicker">Forever in your orbit</div><h2>Little legacies</h2><p class="modal-desc">Every friend you have cared for, kept close.</p><div class="archive">${state.legacy.map(x=>`<article class="archive-card"><div class="archive-top"><span>${x.emoji}</span><div><b>${x.name}</b><small>${x.species} · ${stages[x.stage]} · ${x.days} days</small></div><strong>${x.score} ✦</strong></div><div class="archive-dna">DNA ${x.dna.match(/.{1,4}/g).join(' · ')}</div><div class="archive-bars">${needData.map(([k,icon,label])=>`<div>${icon} ${label}<span>${Math.round(x.stats[k])}%</span></div>`).join('')}</div><div class="archive-foot">Grew through ${x.history.length||1} stages · ${new Date(x.born).toLocaleDateString()}</div></article>`).join('')}</div>`)}
document.getElementById('sleep-btn').onclick=toggleSleep;document.getElementById('legacy-info').onclick=showLegacy;document.getElementById('sound-btn').onclick=()=>{soundOn=!soundOn;document.getElementById('sound-btn').textContent=soundOn?'♫':'♪';notify(soundOn?'A little melody is coming soon!':'Sound off')};
render();setInterval(()=>{if(state.pet){agePet(state.pet);render()}},15000);window.addEventListener('focus',()=>{if(state.pet){agePet(state.pet);render()}});
</script>

